import {
  Injectable,
  Logger,
  NotFoundException,
  ForbiddenException,
  InternalServerErrorException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { DockerService } from '../docker/docker.service';
import { CreateDatabaseDto } from './dto/create-database.dto';
import { DatabaseType, ContainerStatus } from '@generated/prisma';
import { randomBytes } from 'crypto';

@Injectable()
export class DatabasesService {
  private readonly logger = new Logger(DatabasesService.name);

  constructor(
    private prisma: PrismaService,
    private docker: DockerService,
  ) {}

  async create(userId: string, dto: CreateDatabaseDto) {
    const dbPassword = randomBytes(8).toString('hex'); // 16 char password
    const dbUser = dto.type === DatabaseType.POSTGRESQL ? 'portdock' : null;
    const dbName = dto.type === DatabaseType.POSTGRESQL ? 'defaultdb' : null;

    // Create DB record first to get ID for volume naming
    const database = await this.prisma.managedDatabase.create({
      data: {
        userId,
        name: dto.name,
        type: dto.type,
        version: dto.version,
        dbUser,
        dbPassword,
        dbName,
        internalPort: dto.type === DatabaseType.POSTGRESQL ? 5432 : 6379,
        hostPort: 0, // placeholder, will update later
        volumeName: '',
      },
    });

    try {
      const volumeName = `portdock-dbvol-${database.id}`;
      await this.docker.createVolume(volumeName);

      const hostPort = await this.getAvailablePort();

      let imageName = '';
      let envVars: string[] = [];
      let cmd: string[] = [];
      let mountPath = '';

      if (dto.type === DatabaseType.POSTGRESQL) {
        imageName = `postgres:${dto.version === 'latest' ? '15-alpine' : dto.version}`;
        envVars = [
          `POSTGRES_USER=${dbUser}`,
          `POSTGRES_PASSWORD=${dbPassword}`,
          `POSTGRES_DB=${dbName}`,
        ];
        mountPath = '/var/lib/postgresql/data';
      } else if (dto.type === DatabaseType.REDIS) {
        imageName = `redis:${dto.version === 'latest' ? '7-alpine' : dto.version}`;
        cmd = ['redis-server', '--requirepass', dbPassword];
        mountPath = '/data';
      } else {
        throw new Error(`Database type ${dto.type} is not yet supported`);
      }

      await this.docker.pullImage(imageName);

      const containerName = `portdock-db-${database.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Date.now()}`;

      const createOptions: any = {
        name: containerName,
        Image: imageName,
        Env: envVars,
        ExposedPorts: { [`${database.internalPort}/tcp`]: {} },
        HostConfig: {
          PortBindings: {
            [`${database.internalPort}/tcp`]: [{ HostPort: `${hostPort}` }],
          },
          Binds: [`${volumeName}:${mountPath}`],
          RestartPolicy: { Name: 'unless-stopped' },
          Memory: 512 * 1024 * 1024,
          CpuQuota: 50000,
          LogConfig: {
            Type: 'json-file',
            Config: {
              'max-size': '10m',
              'max-file': '3',
            },
          },
        },
      };

      if (cmd.length > 0) {
        createOptions.Cmd = cmd;
      }

      const dockerContainer = await this.docker.createContainer(createOptions);
      const inspect = await dockerContainer.inspect();
      await dockerContainer.start();

      return await this.prisma.managedDatabase.update({
        where: { id: database.id },
        data: {
          dockerContainerId: inspect.Id,
          hostPort,
          volumeName,
          status: ContainerStatus.RUNNING,
        },
      });
    } catch (error) {
      this.logger.error(
        `Failed to provision database: ${error.message}`,
        error.stack,
      );
      await this.prisma.managedDatabase.delete({ where: { id: database.id } });
      throw new InternalServerErrorException('Failed to provision database');
    }
  }

  async findAll(userId: string) {
    return this.prisma.managedDatabase.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
    });
  }

  async findOne(userId: string, id: string) {
    const db = await this.prisma.managedDatabase.findUnique({ where: { id } });
    if (!db) throw new NotFoundException('Database not found');
    if (db.userId !== userId) throw new ForbiddenException();
    return db;
  }

  async remove(userId: string, id: string) {
    const db = await this.findOne(userId, id);

    if (db.dockerContainerId) {
      try {
        await this.docker.stopContainer(db.dockerContainerId);
      } catch (e) {}
      try {
        await this.docker.removeContainer(db.dockerContainerId, true);
      } catch (e) {}
    }

    if (db.volumeName) {
      try {
        await this.docker.removeVolume(db.volumeName);
      } catch (e) {}
    }

    await this.prisma.managedDatabase.delete({ where: { id } });
    return { message: 'Database deleted successfully' };
  }

  // Simplified version of port finding logic
  private async getAvailablePort(): Promise<number> {
    const containers = await this.prisma.container.findMany({
      select: { hostPort: true },
      where: { hostPort: { not: null } },
    });
    const databases = await this.prisma.managedDatabase.findMany({
      select: { hostPort: true },
    });

    const usedPorts = new Set([
      ...containers.map((c) => c.hostPort),
      ...databases.map((d) => d.hostPort),
    ]);

    let port = 40000;
    while (usedPorts.has(port)) {
      port++;
    }
    return port;
  }
}

import {
  Controller,
  Post,
  Param,
  Body,
  UseGuards,
  Request,
  UseInterceptors,
  UploadedFile,
  Ip,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import {
  ApiTags,
  ApiCookieAuth,
  ApiOperation,
  ApiConsumes,
} from '@nestjs/swagger';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { DeploymentsService } from './deployments.service';
import * as path from 'path';

@ApiTags('deployments')
@ApiCookieAuth()
@UseGuards(JwtAuthGuard)
@Controller('deployments')
export class DeploymentsController {
  constructor(private deploymentsService: DeploymentsService) {}

  @Post(':projectId/zip')
  @ApiOperation({ summary: 'Deploy from ZIP file' })
  @ApiConsumes('multipart/form-data')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: diskStorage({
        destination: './uploads/tmp',
        filename: (_req, file, cb) => {
          const uniqueSuffix = `${Date.now()}-${Math.round(Math.random() * 1e9)}`;
          cb(null, `${uniqueSuffix}${path.extname(file.originalname)}`);
        },
      }),
      fileFilter: (_req, file, cb) => {
        if (
          file.mimetype === 'application/zip' ||
          file.originalname.endsWith('.zip')
        ) {
          cb(null, true);
        } else {
          cb(new Error('Only ZIP files are allowed'), false);
        }
      },
      limits: { fileSize: 50 * 1024 * 1024 }, // 50MB
    }),
  )
  deployZip(
    @Request() req: any,
    @Param('projectId') projectId: string,
    @UploadedFile() file: Express.Multer.File,
    @Body('memoryLimit') memoryLimit?: string,
    @Body('cpuLimit') cpuLimit?: string,
    @Body('internalPort') internalPort?: string,
    @Ip() ip?: string,
  ) {
    console.log('--- DEPLOY ZIP PAYLOAD ---', {
      memoryLimit,
      cpuLimit,
      internalPort,
      ip,
    });
    return this.deploymentsService.deployZip(
      req.user.id,
      projectId,
      file,
      Number(memoryLimit) || 512,
      Number(cpuLimit) || 1.0,
      internalPort ? Number(internalPort) : undefined,
      ip,
    );
  }

  @Post(':projectId/github')
  @ApiOperation({ summary: 'Deploy from GitHub repository' })
  deployGithub(
    @Request() req: any,
    @Param('projectId') projectId: string,
    @Body()
    body: {
      repositoryUrl: string;
      branch?: string;
      memoryLimit?: number;
      cpuLimit?: number;
      internalPort?: string;
    },
    @Body('internalPort') internalPort?: string,
    @Ip() ip?: string,
  ) {
    console.log('--- DEPLOY GITHUB PAYLOAD ---', { ...body, ip });
    return this.deploymentsService.deployGithub(
      req.user.id,
      projectId,
      body.repositoryUrl,
      body.branch,
      body.memoryLimit || 512,
      body.cpuLimit || 1.0,
      internalPort ? Number(internalPort) : undefined,
      ip,
    );
  }

  @Post(':projectId/dockerfile')
  @ApiOperation({ summary: 'Deploy from Custom Dockerfile' })
  @ApiConsumes('multipart/form-data')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: diskStorage({
        destination: './uploads/tmp',
        filename: (_req, file, cb) => {
          cb(
            null,
            `dockerfile-${Date.now()}-${Math.round(Math.random() * 1e9)}`,
          );
        },
      }),
      fileFilter: (_req, file, cb) => {
        if (file.originalname.toLowerCase().includes('dockerfile')) {
          cb(null, true);
        } else {
          cb(new Error('Hanya file Dockerfile yang diizinkan!'), false);
        }
      },
      limits: { fileSize: 5 * 1024 * 1024 }, // 5MB for Dockerfile
    }),
  )
  deployDockerfile(
    @Request() req: any,
    @Param('projectId') projectId: string,
    @UploadedFile() file: Express.Multer.File,
    @Body('memoryLimit') memoryLimit?: string,
    @Body('cpuLimit') cpuLimit?: string,
    @Body('internalPort') internalPort?: string,
    @Ip() ip?: string,
  ) {
    console.log('--- DEPLOY DOCKERFILE PAYLOAD ---', {
      memoryLimit,
      cpuLimit,
      internalPort,
      ip,
    });
    return this.deploymentsService.deployDockerfile(
      req.user.id,
      projectId,
      file,
      Number(memoryLimit) || 512,
      Number(cpuLimit) || 1.0,
      internalPort ? Number(internalPort) : undefined,
      ip,
    );
  }
}

import {
  Injectable,
  Logger,
  BadRequestException,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import * as tar from 'tar-fs';
import { PrismaService } from '../prisma/prisma.service';
import { DockerService } from '../docker/docker.service';
import { ActivityLogsService } from '../activity-logs/activity-logs.service';
import { ProjectStatus } from '@generated/prisma';
import { ConfigService } from '@nestjs/config';

import { NginxService } from '../nginx/nginx.service';
import { ArchiveService } from '../archive/archive.service';
import { GitService } from '../git/git.service';

@Injectable()
export class DeploymentsService {
  private readonly logger = new Logger(DeploymentsService.name);

  constructor(
    private prisma: PrismaService,
    private docker: DockerService,
    private activityLogs: ActivityLogsService,
    private config: ConfigService,
    private nginx: NginxService,
    private archive: ArchiveService,
    private git: GitService,
  ) {}

  async deployZip(
    userId: string,
    projectId: string,
    file: Express.Multer.File,
    memoryLimit: number = 512,
    cpuLimit: number = 1.0,
    customInternalPort?: number,
    ip?: string,
  ) {
    const project = await this.verifyProject(projectId, userId);

    const uploadDir = path.resolve(
      process.cwd(),
      this.config.get<string>('UPLOAD_DIR', './uploads'),
    );
    const extractDir = path.join(uploadDir, projectId, Date.now().toString());

    fs.mkdirSync(extractDir, { recursive: true });

    await this.activityLogs.create({
      userId,
      projectId,
      action: 'DEPLOYMENT_STARTED',
      description: `Deployment started for "${project.name}" via ZIP`,
      ipAddress: ip,
    });

    await this.prisma.project.update({
      where: { id: projectId },
      data: { status: ProjectStatus.BUILDING },
    });

    try {
      await this.archive.extractAndFlatten(file.path, extractDir);

      const imageName = `portdock-${projectId}`.toLowerCase();
      const imageTag = `v${Date.now()}`;
      const dockerfilePath = path.join(extractDir, 'Dockerfile');

      if (project.templateId === 'STATIC_NGINX') {
        fs.writeFileSync(
          dockerfilePath,
          `FROM nginx:latest\nCOPY . /usr/share/nginx/html\nEXPOSE 80\n`,
        );
        this.logger.log(
          `Generated STATIC_NGINX Dockerfile for ${project.name}`,
        );
      } else if (project.templateId === 'STATIC_APACHE') {
        fs.writeFileSync(
          dockerfilePath,
          `FROM httpd:latest\nCOPY . /usr/local/apache2/htdocs/\nEXPOSE 80\n`,
        );
        this.logger.log(
          `Generated STATIC_APACHE Dockerfile for ${project.name}`,
        );
      } else if (project.templateId === 'PHP_APACHE') {
        fs.writeFileSync(
          dockerfilePath,
          `FROM php:8.2-apache\nCOPY . /var/www/html/\nEXPOSE 80\n`,
        );
        this.logger.log(`Generated PHP_APACHE Dockerfile for ${project.name}`);
      }

      if (fs.existsSync(dockerfilePath)) {
        const tarStream = tar.pack(extractDir);
        await this.docker.buildImage(tarStream, imageName, imageTag);
      } else {
        await this.docker.buildWithNixpacks(extractDir, imageName, imageTag);
      }

      // Find available port
      const hostPort = await this.getAvailablePort();
      const detectedPort = await this.docker.getExposedPort(
        `${imageName}:${imageTag}`,
      );
      const internalPort = customInternalPort || detectedPort;

      // Parse environment variables
      let dockerEnv = [`PORT=${internalPort}`];
      if (project.envVars && typeof project.envVars === 'object') {
        const envRecord = project.envVars as Record<string, string>;
        const envArray = Object.entries(envRecord).map(([k, v]) => `${k}=${v}`);
        dockerEnv = [...dockerEnv, ...envArray];
      }

      // Create Docker container
      const dockerContainer = await this.docker.createContainer({
        name: `${project.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Date.now()}`,
        Image: `${imageName}:${imageTag}`,
        Env: dockerEnv,
        ExposedPorts: { [`${internalPort}/tcp`]: {} },
        HostConfig: {
          Memory: Math.min(memoryLimit, 512) * 1024 * 1024,
          CpuQuota: Math.floor(Math.min(cpuLimit, 1.0) * 100000),
          PortBindings: {
            [`${internalPort}/tcp`]: [{ HostPort: `${hostPort}` }],
          },
          RestartPolicy: { Name: 'unless-stopped' },
          LogConfig: {
            Type: 'json-file',
            Config: {
              'max-size': '10m',
              'max-file': '3',
            },
          },
        },
      });

      const inspect = await dockerContainer.inspect();
      await dockerContainer.start();

      const containerName = `${project.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Date.now()}`;
      const container = await this.prisma.container.create({
        data: {
          projectId,
          dockerContainerId: inspect.Id,
          name: containerName,
          imageName,
          imageTag,
          internalPort,
          hostPort,
          status: 'RUNNING',
          memoryLimit,
          cpuLimit,
        },
      });

      await this.cleanupOldContainers(projectId, container.id);

      await this.prisma.project.update({
        where: { id: projectId },
        data: { status: ProjectStatus.ACTIVE },
      });

      await this.activityLogs.create({
        userId,
        projectId,
        action: 'DEPLOYMENT_SUCCESS',
        description: `Deployment succeeded for "${project.name}"`,
        ipAddress: ip,
      });

      // Generate Nginx config if domain exists
      if (project.domain) {
        const domain = project.domain;
        await this.nginx.generateHttpConfig(domain, hostPort);

        // Attempt Let's Encrypt SSL in the background!
        // Do not block the HTTP response waiting for certbot to finish.
        const userEmail = project.user?.email || 'admin@portdock.my.id';
        this.nginx
          .requestSsl(domain, userEmail)
          .then(async (sslSuccess) => {
            if (sslSuccess) {
              await this.nginx.generateHttpsConfig(domain, hostPort);
            }
          })
          .catch((err) => this.logger.error('Background SSL Error', err));
      }

      // Cleanup
      this.archive.cleanup(extractDir, file.path);

      return { message: 'Deployment successful', container };
    } catch (err) {
      this.logger.error('Deployment failed', err);

      await this.prisma.project.update({
        where: { id: projectId },
        data: { status: ProjectStatus.FAILED },
      });

      await this.activityLogs.create({
        userId,
        projectId,
        action: 'DEPLOYMENT_FAILED',
        description: `Deployment failed: ${err.message}`,
        ipAddress: ip,
      });

      this.archive.cleanup(extractDir, file.path);

      throw new BadRequestException(`Deployment failed: ${err.message}`);
    }
  }

  async deployGithub(
    userId: string,
    projectId: string,
    repositoryUrl: string,
    branch: string = 'main',
    memoryLimit: number = 512,
    cpuLimit: number = 1.0,
    customInternalPort?: number,
    ip?: string,
  ) {
    const project = await this.verifyProject(projectId, userId);

    const uploadDir = path.resolve(
      process.cwd(),
      this.config.get<string>('UPLOAD_DIR', './uploads'),
    );
    const cloneDir = path.join(uploadDir, projectId, `github-${Date.now()}`);

    fs.mkdirSync(path.dirname(cloneDir), { recursive: true });

    await this.activityLogs.create({
      userId,
      projectId,
      action: 'DEPLOYMENT_STARTED',
      description: `Deployment started for "${project.name}" via GitHub`,
      ipAddress: ip,
    });

    await this.prisma.project.update({
      where: { id: projectId },
      data: { status: ProjectStatus.BUILDING, repositoryUrl },
    });

    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: { sshPrivateKey: true, githubToken: true },
    });

    try {
      // Clone repository
      this.git.cloneRepository(repositoryUrl, branch, cloneDir, {
        sshPrivateKey: user?.sshPrivateKey,
        githubToken: user?.githubToken,
      });

      const dockerfilePath = path.join(cloneDir, 'Dockerfile');
      const imageName = `portdock-${projectId}`.toLowerCase();
      const imageTag = `v${Date.now()}`;

      if (project.templateId === 'STATIC_NGINX') {
        fs.writeFileSync(
          dockerfilePath,
          `FROM nginx:latest\nCOPY . /usr/share/nginx/html\nEXPOSE 80\n`,
        );
        this.logger.log(
          `Generated STATIC_NGINX Dockerfile for ${project.name}`,
        );
      } else if (project.templateId === 'STATIC_APACHE') {
        fs.writeFileSync(
          dockerfilePath,
          `FROM httpd:latest\nCOPY . /usr/local/apache2/htdocs/\nEXPOSE 80\n`,
        );
        this.logger.log(
          `Generated STATIC_APACHE Dockerfile for ${project.name}`,
        );
      } else if (project.templateId === 'PHP_APACHE') {
        fs.writeFileSync(
          dockerfilePath,
          `FROM php:8.2-apache\nCOPY . /var/www/html/\nEXPOSE 80\n`,
        );
        this.logger.log(`Generated PHP_APACHE Dockerfile for ${project.name}`);
      }

      if (fs.existsSync(dockerfilePath)) {
        const tarStream = tar.pack(cloneDir);
        await this.docker.buildImage(tarStream, imageName, imageTag);
      } else {
        await this.docker.buildWithNixpacks(cloneDir, imageName, imageTag);
      }

      const hostPort = await this.getAvailablePort();
      const detectedPort = await this.docker.getExposedPort(
        `${imageName}:${imageTag}`,
      );
      const internalPort = customInternalPort || detectedPort;

      // Parse environment variables
      let dockerEnv = [`PORT=${internalPort}`];
      if (project.envVars && typeof project.envVars === 'object') {
        const envRecord = project.envVars as Record<string, string>;
        const envArray = Object.entries(envRecord).map(([k, v]) => `${k}=${v}`);
        dockerEnv = [...dockerEnv, ...envArray];
      }

      const containerName = `${project.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Date.now()}`;
      const dockerContainer = await this.docker.createContainer({
        name: containerName,
        Image: `${imageName}:${imageTag}`,
        Env: dockerEnv,
        ExposedPorts: { [`${internalPort}/tcp`]: {} },
        HostConfig: {
          Memory: Math.min(memoryLimit, 512) * 1024 * 1024,
          CpuQuota: Math.floor(Math.min(cpuLimit, 1.0) * 100000),
          PortBindings: {
            [`${internalPort}/tcp`]: [{ HostPort: `${hostPort}` }],
          },
          RestartPolicy: { Name: 'unless-stopped' },
          LogConfig: {
            Type: 'json-file',
            Config: {
              'max-size': '10m',
              'max-file': '3',
            },
          },
        },
      });

      const inspect = await dockerContainer.inspect();
      await dockerContainer.start();

      const container = await this.prisma.container.create({
        data: {
          projectId,
          dockerContainerId: inspect.Id,
          name: containerName,
          imageName,
          imageTag,
          internalPort,
          hostPort,
          status: 'RUNNING',
          memoryLimit: Math.min(memoryLimit, 512),
          cpuLimit: Math.min(cpuLimit, 1.0),
        },
      });

      await this.cleanupOldContainers(projectId, container.id);

      await this.prisma.project.update({
        where: { id: projectId },
        data: { status: ProjectStatus.ACTIVE },
      });

      await this.activityLogs.create({
        userId,
        projectId,
        action: 'DEPLOYMENT_SUCCESS',
        description: `GitHub deployment succeeded for "${project.name}"`,
        ipAddress: ip,
      });

      // Generate Nginx config if domain exists
      if (project.domain) {
        const domain = project.domain;
        await this.nginx.generateHttpConfig(domain, hostPort);

        // Attempt Let's Encrypt SSL in the background!
        const userEmail = project.user?.email || 'admin@portdock.my.id';
        this.nginx
          .requestSsl(domain, userEmail)
          .then(async (sslSuccess) => {
            if (sslSuccess) {
              await this.nginx.generateHttpsConfig(domain, hostPort);
            }
          })
          .catch((err) => this.logger.error('Background SSL Error', err));
      }

      this.archive.cleanup(cloneDir);

      return { message: 'GitHub deployment successful', container };
    } catch (err) {
      this.logger.error('GitHub deployment failed', err);

      await this.prisma.project.update({
        where: { id: projectId },
        data: { status: ProjectStatus.FAILED },
      });

      await this.activityLogs.create({
        userId,
        projectId,
        action: 'DEPLOYMENT_FAILED',
        description: `GitHub deployment failed: ${err.message}`,
        ipAddress: ip,
      });

      this.archive.cleanup(cloneDir);

      throw new BadRequestException(`Deployment failed: ${err.message}`);
    }
  }

  async deployDockerfile(
    userId: string,
    projectId: string,
    file: Express.Multer.File,
    memoryLimit: number = 512,
    cpuLimit: number = 1.0,
    customInternalPort?: number,
    ip?: string,
  ) {
    const project = await this.verifyProject(projectId, userId);

    const uploadDir = path.resolve(
      process.cwd(),
      this.config.get<string>('UPLOAD_DIR', './uploads'),
    );
    const extractDir = path.join(
      uploadDir,
      projectId,
      `dockerfile-${Date.now()}`,
    );

    fs.mkdirSync(extractDir, { recursive: true });

    await this.activityLogs.create({
      userId,
      projectId,
      action: 'DEPLOYMENT_STARTED',
      description: `Deployment started for "${project.name}" via Custom Dockerfile`,
      ipAddress: ip,
    });

    await this.prisma.project.update({
      where: { id: projectId },
      data: { status: ProjectStatus.BUILDING },
    });

    try {
      // Move uploaded Dockerfile to extractDir
      const destPath = path.join(extractDir, 'Dockerfile');
      fs.copyFileSync(file.path, destPath);

      const imageName = `portdock-${projectId}`.toLowerCase();
      const imageTag = `v${Date.now()}`;

      // Build Image
      const tarStream = tar.pack(extractDir);
      await this.docker.buildImage(tarStream, imageName, imageTag);

      // Find available port
      const hostPort = await this.getAvailablePort();
      const detectedPort = await this.docker.getExposedPort(
        `${imageName}:${imageTag}`,
      );
      const internalPort = customInternalPort || detectedPort;

      // Parse environment variables
      let dockerEnv = [`PORT=${internalPort}`];
      if (project.envVars && typeof project.envVars === 'object') {
        const envRecord = project.envVars as Record<string, string>;
        const envArray = Object.entries(envRecord).map(([k, v]) => `${k}=${v}`);
        dockerEnv = [...dockerEnv, ...envArray];
      }

      // Create Docker container
      const dockerContainer = await this.docker.createContainer({
        name: `${project.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Date.now()}`,
        Image: `${imageName}:${imageTag}`,
        Env: dockerEnv,
        ExposedPorts: { [`${internalPort}/tcp`]: {} },
        HostConfig: {
          Memory: Math.min(memoryLimit, 512) * 1024 * 1024,
          CpuQuota: Math.floor(Math.min(cpuLimit, 1.0) * 100000),
          PortBindings: {
            [`${internalPort}/tcp`]: [{ HostPort: `${hostPort}` }],
          },
          RestartPolicy: { Name: 'always' },
        },
      });

      const inspect = await dockerContainer.inspect();
      await dockerContainer.start();

      const containerName = `${project.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Date.now()}`;
      const container = await this.prisma.container.create({
        data: {
          projectId,
          dockerContainerId: inspect.Id,
          name: containerName,
          imageName,
          imageTag,
          internalPort,
          hostPort,
          status: 'RUNNING',
          memoryLimit,
          cpuLimit,
        },
      });

      await this.cleanupOldContainers(projectId, container.id);

      await this.prisma.project.update({
        where: { id: projectId },
        data: { status: ProjectStatus.ACTIVE },
      });

      await this.activityLogs.create({
        userId,
        projectId,
        action: 'DEPLOYMENT_SUCCESS',
        description: `Custom Dockerfile deployment completed successfully for "${project.name}"`,
        ipAddress: ip,
      });

      if (project.domain) {
        const domain = project.domain;
        await this.nginx.generateHttpConfig(domain, hostPort);

        const userEmail = project.user?.email || 'admin@portdock.my.id';
        this.nginx
          .requestSsl(domain, userEmail)
          .then(async (sslSuccess) => {
            if (sslSuccess) {
              await this.nginx.generateHttpsConfig(domain, hostPort);
            }
          })
          .catch((err) => this.logger.error('Background SSL Error', err));
      }

      this.archive.cleanup(extractDir, file.path);

      return {
        message: 'Deployment successful',
        container: dockerContainer.id,
      };
    } catch (err) {
      this.logger.error('Custom Dockerfile deployment failed', err);

      await this.prisma.project.update({
        where: { id: projectId },
        data: { status: ProjectStatus.FAILED },
      });

      await this.activityLogs.create({
        userId,
        projectId,
        action: 'DEPLOYMENT_FAILED',
        description: `Custom Dockerfile deployment failed: ${err.message}`,
        ipAddress: ip,
      });

      this.archive.cleanup(extractDir, file.path);

      throw new BadRequestException(`Deployment failed: ${err.message}`);
    }
  }

  private async verifyProject(projectId: string, userId: string) {
    const project = await this.prisma.project.findUnique({
      where: { id: projectId },
      include: { user: { select: { email: true } } },
    });
    if (!project) throw new NotFoundException('Project not found');
    if (project.userId !== userId) throw new ForbiddenException();
    return project;
  }

  private async getAvailablePort(): Promise<number> {
    const usedPorts = await this.prisma.container.findMany({
      select: { hostPort: true },
      where: { hostPort: { not: null } },
    });
    const used = new Set(usedPorts.map((c) => c.hostPort));
    for (let port = 8000; port <= 9999; port++) {
      if (!used.has(port)) return port;
    }
    throw new Error('No available ports');
  }

  private async cleanupOldContainers(
    projectId: string,
    excludeContainerId: string,
  ) {
    try {
      const oldContainers = await this.prisma.container.findMany({
        where: {
          projectId,
          id: { not: excludeContainerId },
        },
      });

      for (const old of oldContainers) {
        if (old.dockerContainerId) {
          try {
            await this.docker.removeContainer(old.dockerContainerId, true);
            this.logger.log(
              `Cleaned up old container ${old.dockerContainerId}`,
            );
            if (old.imageName && old.imageTag) {
              await this.docker.removeImage(`${old.imageName}:${old.imageTag}`);
            }
          } catch (e) {
            this.logger.error(
              `Failed to remove old docker container or image: ${e.message}`,
            );
          }
        }
        await this.prisma.container.delete({ where: { id: old.id } });
      }
    } catch (err) {
      this.logger.error(
        `Error during cleanup of old containers: ${err.message}`,
      );
    }
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import Dockerode from 'dockerode';
import * as path from 'path';
import * as fs from 'fs';
import { spawn } from 'child_process';

@Injectable()
export class DockerService implements OnModuleInit {
  private docker: Dockerode;
  private readonly logger = new Logger(DockerService.name);
  private nginxContainerId: string | null = null;

  constructor() {
    this.docker = new Dockerode({ socketPath: '/var/run/docker.sock' });
  }

  async onModuleInit() {
    await this.ensureSystemContainers();
  }

  private async ensureSystemContainers() {
    this.logger.log('Ensuring system containers are running...');
    const containers = await this.listContainers(true);
    const nginxContainer = containers.find((c) =>
      c.Names.includes('/portdock-nginx'),
    );

    if (nginxContainer) {
      this.nginxContainerId = nginxContainer.Id;
      if (nginxContainer.State !== 'running') {
        this.logger.log('Starting portdock-nginx container...');
        if (this.nginxContainerId) {
          await this.startContainer(this.nginxContainerId);
        }
      }
    } else {
      this.logger.log('Creating portdock-nginx container...');
      const confDir = path.resolve(process.cwd(), 'nginx-conf.d');
      if (!fs.existsSync(confDir)) {
        fs.mkdirSync(confDir, { recursive: true });
      }

      const hasImage = await this.imageExists('nginx:alpine');
      if (!hasImage) {
        this.logger.log('Pulling nginx:alpine image...');
        await this.pullImage('nginx:alpine');
      }

      const certbotConfDir = path.resolve(process.cwd(), 'certbot-conf');
      const certbotWwwDir = path.resolve(process.cwd(), 'certbot-www');

      if (!fs.existsSync(certbotConfDir))
        fs.mkdirSync(certbotConfDir, { recursive: true });
      if (!fs.existsSync(certbotWwwDir))
        fs.mkdirSync(certbotWwwDir, { recursive: true });

      const container = await this.createContainer({
        name: 'portdock-nginx',
        Image: 'nginx:alpine',
        ExposedPorts: { '80/tcp': {}, '443/tcp': {} },
        HostConfig: {
          PortBindings: {
            '80/tcp': [{ HostPort: '80' }],
            '443/tcp': [{ HostPort: '443' }],
          },
          Binds: [
            `${confDir}:/etc/nginx/conf.d`,
            `${certbotConfDir}:/etc/letsencrypt`,
            `${certbotWwwDir}:/var/www/certbot`,
          ],
          RestartPolicy: { Name: 'always' },
          NetworkMode: 'host', // For easier localhost routing, or bridge mapping
          LogConfig: {
            Type: 'json-file',
            Config: {
              'max-size': '10m',
              'max-file': '3',
            },
          },
        },
      });
      this.nginxContainerId = container.id;
      await container.start();
      this.logger.log('portdock-nginx container started.');
    }
  }

  async getSystemNginxContainerId(): Promise<string | null> {
    return this.nginxContainerId;
  }

  getDocker(): Dockerode {
    return this.docker;
  }

  async listContainers(all = true) {
    return this.docker.listContainers({ all });
  }

  async getContainer(dockerContainerId: string) {
    return this.docker.getContainer(dockerContainerId);
  }

  async inspectContainer(dockerContainerId: string) {
    const container = this.docker.getContainer(dockerContainerId);
    return container.inspect();
  }

  async startContainer(dockerContainerId: string) {
    const container = this.docker.getContainer(dockerContainerId);
    try {
      await container.start();
    } catch (error) {
      if (error.statusCode === 304) {
        this.logger.log(`Container ${dockerContainerId} is already running.`);
        return;
      }
      throw error;
    }
  }

  async stopContainer(dockerContainerId: string) {
    const container = this.docker.getContainer(dockerContainerId);
    await container.stop();
  }

  async restartContainer(dockerContainerId: string) {
    const container = this.docker.getContainer(dockerContainerId);
    await container.restart();
  }

  async removeContainer(dockerContainerId: string, force = false) {
    const container = this.docker.getContainer(dockerContainerId);
    await container.remove({ force });
  }

  async removeImage(imageName: string) {
    try {
      const image = this.docker.getImage(imageName);
      await image.remove({ force: true });
      this.logger.log(`Successfully removed image: ${imageName}`);
    } catch (err) {
      this.logger.warn(`Failed to remove image ${imageName}: ${err.message}`);
    }
  }

  async createVolume(volumeName: string) {
    try {
      // Check if volume already exists
      const volumeInfo = await this.docker
        .getVolume(volumeName)
        .inspect()
        .catch(() => null);
      if (volumeInfo) return volumeInfo;

      // Create new volume
      const volume = await this.docker.createVolume({
        Name: volumeName,
      });
      return volume;
    } catch (error) {
      this.logger.error(
        `Failed to create volume ${volumeName}: ${error.message}`,
      );
      throw error;
    }
  }

  async removeVolume(volumeName: string): Promise<void> {
    try {
      const volume = this.docker.getVolume(volumeName);
      await volume.remove();
    } catch (error) {
      this.logger.error(
        `Failed to remove volume ${volumeName}: ${error.message}`,
      );
      throw error;
    }
  }

  async getContainerStats(dockerContainerId: string): Promise<any> {
    const container = this.docker.getContainer(dockerContainerId);
    return new Promise((resolve, reject) => {
      container.stats({ stream: false }, (err, data) => {
        if (err) {
          reject(err);
        } else {
          resolve(data);
        }
      });
    });
  }

  async buildImage(
    tarStream: NodeJS.ReadableStream,
    imageName: string,
    imageTag = 'latest',
  ): Promise<void> {
    return new Promise((resolve, reject) => {
      this.docker.buildImage(
        tarStream as any,
        { t: `${imageName}:${imageTag}` },
        (err, stream) => {
          if (err) {
            reject(err);
            return;
          }
          this.docker.modem.followProgress(
            stream,
            (err2, output) => {
              if (err2) {
                this.logger.error('Docker Build Error', err2);
                reject(err2);
              } else {
                resolve();
              }
            },
            (event) => {
              if (event.stream) {
                process.stdout.write(event.stream);
              } else if (event.errorDetail) {
                this.logger.error(
                  `Docker Build Event Error: ${event.errorDetail.message}`,
                );
                reject(new Error(event.errorDetail.message));
              }
            },
          );
        },
      );
    });
  }

  async buildWithNixpacks(
    dir: string,
    imageName: string,
    imageTag = 'latest',
  ): Promise<void> {
    return new Promise((resolve, reject) => {
      const tag = `${imageName}:${imageTag}`;
      this.logger.log(`Starting Nixpacks build for ${tag}`);
      const child = spawn('nixpacks', ['build', dir, '--name', tag]);

      child.stdout.on('data', (data) => {
        process.stdout.write(data);
      });

      child.stderr.on('data', (data) => {
        process.stdout.write(data);
      });

      child.on('close', (code) => {
        if (code === 0) {
          this.logger.log(`Nixpacks build successful for ${tag}`);
          resolve();
        } else {
          reject(new Error(`Nixpacks build failed with exit code ${code}`));
        }
      });

      child.on('error', (err) => {
        this.logger.error(
          `Failed to start Nixpacks. Is it installed? Error: ${err.message}`,
        );
        reject(err);
      });
    });
  }

  async getExposedPort(imageName: string): Promise<number> {
    try {
      const image = await this.docker.getImage(imageName).inspect();
      const exposedPorts = image.Config.ExposedPorts;
      if (exposedPorts) {
        const ports = Object.keys(exposedPorts);
        if (ports.length > 0) {
          return parseInt(ports[0].split('/')[0], 10);
        }
      }
    } catch (e) {
      this.logger.warn(`Failed to inspect image port: ${e.message}`);
    }
    return 3000;
  }

  async pullImage(imageName: string): Promise<void> {
    return new Promise((resolve, reject) => {
      this.docker.pull(imageName, (err: any, stream: any) => {
        if (err) {
          reject(err);
          return;
        }
        this.docker.modem.followProgress(stream, (err2: any) => {
          if (err2) reject(err2);
          else resolve();
        });
      });
    });
  }

  async createContainer(options: Dockerode.ContainerCreateOptions) {
    return this.docker.createContainer(options);
  }

  async imageExists(imageName: string): Promise<boolean> {
    try {
      const image = this.docker.getImage(imageName);
      await image.inspect();
      return true;
    } catch {
      return false;
    }
  }

  parseStats(stats: any) {
    const cpuDelta =
      stats.cpu_stats.cpu_usage.total_usage -
      stats.precpu_stats.cpu_usage.total_usage;
    const systemDelta =
      stats.cpu_stats.system_cpu_usage - stats.precpu_stats.system_cpu_usage;
    const numCpus = stats.cpu_stats.online_cpus || 1;
    const cpuPercent =
      systemDelta > 0 ? (cpuDelta / systemDelta) * numCpus * 100.0 : 0;

    const memUsage = stats.memory_stats.usage || 0;
    const memLimit = stats.memory_stats.limit || 1;
    const memPercent = (memUsage / memLimit) * 100.0;

    const networks = stats.networks || {};
    let netRx = 0;
    let netTx = 0;
    for (const iface of Object.values(networks)) {
      netRx += iface.rx_bytes || 0;
      netTx += iface.tx_bytes || 0;
    }

    return {
      cpuPercent: Math.round(cpuPercent * 100) / 100,
      memUsageMb: Math.round(memUsage / 1024 / 1024),
      memLimitMb: Math.round(memLimit / 1024 / 1024),
      memPercent: Math.round(memPercent * 100) / 100,
      netRxMb: Math.round(netRx / 1024 / 1024),
      netTxMb: Math.round(netTx / 1024 / 1024),
    };
  }
}

