import { NestFactory } from '@nestjs/core';
import { NestExpressApplication } from '@nestjs/platform-express';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { AppModule } from './app.module';
import { ZodValidationPipe } from 'nestjs-zod';
import helmet from 'helmet';
import * as fs from 'fs';
import cookieParser from 'cookie-parser';

async function bootstrap() {
  const app = await NestFactory.create<NestExpressApplication>(AppModule);

  // Trust proxy is required to get the real IP address of users when deployed behind Nginx or Cloudflare
  app.set('trust proxy', 1);

  // Ensure uploads directory exists
  fs.mkdirSync('./uploads/tmp', { recursive: true });

  // Security
  app.use(
    helmet({
      contentSecurityPolicy: false, // Disabling this because it blocks Swagger UI
    }),
  );
  app.use(cookieParser());

  // Enterprise-level strict CORS policy
  const isProduction = process.env.NODE_ENV === 'production';
  const allowedOrigins = isProduction
    ? ['https://portdock.my.id', 'https://www.portdock.my.id']
    : [
        'http://localhost:3000',
        'http://127.0.0.1:3000',
        'http://localhost:3001',
        'http://127.0.0.1:3001',
      ];

  // CORS
  app.enableCors({
    origin: allowedOrigins,
    credentials: true,
  });

  // Global Zod validation pipe
  app.useGlobalPipes(new ZodValidationPipe());

  // API prefix
  app.setGlobalPrefix('api');

  // Swagger docs
  const config = new DocumentBuilder()
    .setTitle('Portdock API')
    .setDescription('Portdock - Docker Deployment Platform API')
    .setVersion('1.0')
    .addCookieAuth('access_token')
    .build();
  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api/docs', app, document);

  const port = process.env.PORT ?? 3001;
  await app.listen(port);
  console.log(`Server is running at http://localhost:${port}`);
  console.log(`Swagger docs at http://localhost:${port}/api/docs`);
}
bootstrap();

import { Controller, Get, Param, UseGuards, Request } from '@nestjs/common';
import { ApiTags, ApiCookieAuth, ApiOperation } from '@nestjs/swagger';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { MonitoringService } from './monitoring.service';

@ApiTags('monitoring')
@ApiCookieAuth()
@UseGuards(JwtAuthGuard)
@Controller('monitoring')
export class MonitoringController {
  constructor(private monitoringService: MonitoringService) {}

  @Get('dashboard')
  @ApiOperation({ summary: 'Get dashboard stats' })
  getDashboard(@Request() req: any) {
    return this.monitoringService.getDashboardStats(req.user.id);
  }

  @Get(':containerId/stats')
  @ApiOperation({ summary: 'Get container resource stats' })
  getStats(@Request() req: any, @Param('containerId') containerId: string) {
    return this.monitoringService.getContainerStats(containerId, req.user.id);
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { DockerService } from '../docker/docker.service';

@Injectable()
export class MonitoringService {
  constructor(
    private prisma: PrismaService,
    private docker: DockerService,
  ) {}

  async getContainerStats(containerId: string, userId: string) {
    const container = await this.prisma.container.findUnique({
      where: { id: containerId },
      include: { project: { select: { userId: true } } },
    });

    if (!container) throw new NotFoundException('Container not found');
    if (container.project.userId !== userId) throw new ForbiddenException();
    if (!container.dockerContainerId)
      throw new NotFoundException('Docker container not found');

    try {
      const rawStats = await this.docker.getContainerStats(
        container.dockerContainerId,
      );
      const parsed = this.docker.parseStats(rawStats);
      return {
        containerId,
        name: container.name,
        status: container.status,
        ...parsed,
        timestamp: new Date().toISOString(),
      };
    } catch {
      return {
        containerId,
        name: container.name,
        status: container.status,
        cpuPercent: 0,
        memUsageMb: 0,
        memLimitMb: 0,
        memPercent: 0,
        netRxMb: 0,
        netTxMb: 0,
        timestamp: new Date().toISOString(),
      };
    }
  }

  async getDashboardStats(userId: string) {
    const [totalProjects, totalContainers, runningContainers] =
      await Promise.all([
        this.prisma.project.count({ where: { userId } }),
        this.prisma.container.count({ where: { project: { userId } } }),
        this.prisma.container.count({
          where: { project: { userId }, status: 'RUNNING' },
        }),
      ]);

    const recentProjects = await this.prisma.project.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      take: 5,
      include: { containers: { select: { id: true, status: true } } },
    });

    const recentActivity = await this.prisma.activityLog.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      take: 8,
      include: { project: { select: { id: true, name: true } } },
    });

    const totalDeployments = await this.prisma.activityLog.count({
      where: {
        userId,
        action: { in: ['DEPLOYMENT_SUCCESS', 'DEPLOYMENT_STARTED'] },
      },
    });

    // Generate realistic mock time-series data for the chart
    // In a real production system, this would be queried from Prometheus or InfluxDB
    const chartData: any[] = [];
    const now = new Date();
    const baseCpu = runningContainers > 0 ? 15 + runningContainers * 5 : 0;
    const baseRam = runningContainers > 0 ? 20 + runningContainers * 8 : 0;

    for (let i = 6; i >= 0; i--) {
      const time = new Date(now.getTime() - i * 5 * 60000); // Past 30 mins, 5 min intervals
      chartData.push({
        time: time.toLocaleTimeString([], {
          hour: '2-digit',
          minute: '2-digit',
        }),
        cpu:
          runningContainers > 0
            ? Math.max(
                0,
                Math.min(100, Math.floor(baseCpu + (Math.random() * 15 - 5))),
              )
            : 0,
        ram:
          runningContainers > 0
            ? Math.max(
                0,
                Math.min(100, Math.floor(baseRam + (Math.random() * 10 - 3))),
              )
            : 0,
      });
    }

    return {
      totalProjects,
      totalContainers,
      runningContainers,
      totalDeployments,
      recentProjects,
      recentActivity,
      chartData,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import { DockerService } from '../docker/docker.service';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class NginxService {
  private readonly logger = new Logger(NginxService.name);
  private readonly confDir: string;

  constructor(
    private dockerService: DockerService,
    private configService: ConfigService,
  ) {
    this.confDir = path.resolve(process.cwd(), 'nginx-conf.d');
    if (!fs.existsSync(this.confDir)) {
      fs.mkdirSync(this.confDir, { recursive: true });
    }
  }

  /**
   * Menghasilkan HTTP file Nginx (port 80) yang mendukung Let's Encrypt webroot
   */
  async generateHttpConfig(domain: string, hostPort: number): Promise<void> {
    const confContent = `
server {
    listen 80;
    server_name ${domain};

    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location / {
        proxy_pass http://172.17.0.1:${hostPort};
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
`;
    const confPath = path.join(this.confDir, `${domain}.conf`);
    fs.writeFileSync(confPath, confContent);
    this.logger.log(
      `HTTP Nginx config created for ${domain} -> Port ${hostPort}`,
    );

    await this.reloadNginx();
  }

  /**
   * Meminta sertifikat SSL dari Let's Encrypt
   */
  async requestSsl(domain: string, email: string): Promise<boolean> {
    if (process.env.NODE_ENV === 'development') {
      this.logger.log(
        `Skipping SSL request for ${domain} in development mode.`,
      );
      return false; // Skip SSL generation locally
    }

    this.logger.log(`Requesting SSL for ${domain} with email ${email}...`);
    try {
      const certbotConfDir = path.resolve(process.cwd(), 'certbot-conf');
      const certbotWwwDir = path.resolve(process.cwd(), 'certbot-www');

      // Check for Wildcard SSL Certificate first
      const baseDomain = this.configService.get<string>('BASE_DOMAIN');
      if (baseDomain && domain.endsWith(`.${baseDomain}`)) {
        const wildcardPath = path.join(
          certbotConfDir,
          'live',
          baseDomain,
          'fullchain.pem',
        );
        if (fs.existsSync(wildcardPath)) {
          this.logger.log(
            `Wildcard certificate for ${baseDomain} found. Using it for ${domain}.`,
          );
          return true;
        }
      }

      // Check if certificate already exists
      const certPath = path.join(
        certbotConfDir,
        'live',
        domain,
        'fullchain.pem',
      );
      if (fs.existsSync(certPath)) {
        this.logger.log(`Certificate for ${domain} already exists.`);
        return true;
      }

      // Pastikan image certbot ada
      const hasImage = await this.dockerService.imageExists(
        'certbot/certbot:latest',
      );
      if (!hasImage) {
        this.logger.log('Pulling certbot/certbot:latest image...');
        await this.dockerService.pullImage('certbot/certbot:latest');
      }

      const container = await this.dockerService.getDocker().createContainer({
        Image: 'certbot/certbot:latest',
        Cmd: [
          'certonly',
          '--webroot',
          '-w',
          '/var/www/certbot',
          '-d',
          domain,
          '--email',
          email,
          '--agree-tos',
          '--non-interactive',
        ],
        HostConfig: {
          Binds: [
            `${certbotConfDir}:/etc/letsencrypt`,
            `${certbotWwwDir}:/var/www/certbot`,
          ],
        },
      });

      await container.start();
      const stream = await container.logs({
        follow: true,
        stdout: true,
        stderr: true,
      });
      stream.on('data', (chunk) =>
        this.logger.debug(`Certbot: ${chunk.toString('utf8')}`),
      );

      const result = await container.wait();

      try {
        await container.remove();
      } catch (e) {}

      if (result.StatusCode === 0) {
        this.logger.log(`SSL certificate successfully generated for ${domain}`);
        return true;
      } else {
        this.logger.warn(`Certbot failed with status ${result.StatusCode}`);
        return false;
      }
    } catch (err) {
      this.logger.error(`Failed to request SSL for ${domain}`, err);
      return false;
    }
  }

  /**
   * Menghasilkan HTTPS file Nginx (port 443 + redirect) setelah SSL berhasil
   */
  async generateHttpsConfig(domain: string, hostPort: number): Promise<void> {
    const baseDomain = this.configService.get<string>('BASE_DOMAIN');
    let certPath = `/etc/letsencrypt/live/${domain}/fullchain.pem`;
    let keyPath = `/etc/letsencrypt/live/${domain}/privkey.pem`;

    if (baseDomain && domain.endsWith(`.${baseDomain}`)) {
      const certbotConfDir = path.resolve(process.cwd(), 'certbot-conf');
      const wildcardPath = path.join(
        certbotConfDir,
        'live',
        baseDomain,
        'fullchain.pem',
      );
      if (fs.existsSync(wildcardPath)) {
        certPath = `/etc/letsencrypt/live/${baseDomain}/fullchain.pem`;
        keyPath = `/etc/letsencrypt/live/${baseDomain}/privkey.pem`;
      }
    }

    const confContent = `
server {
    listen 80;
    server_name ${domain};

    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 443 ssl;
    server_name ${domain};

    ssl_certificate ${certPath};
    ssl_certificate_key ${keyPath};

    location / {
        proxy_pass http://172.17.0.1:${hostPort};
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
`;
    const confPath = path.join(this.confDir, `${domain}.conf`);
    fs.writeFileSync(confPath, confContent);
    this.logger.log(
      `HTTPS Nginx config created for ${domain} -> Port ${hostPort}`,
    );

    await this.reloadNginx();
  }

  /**
   * Fungsi wrapper untuk backwards compatibility.
   * Ini dulu dipanggil langsung, sekarang hanya nama alias.
   */
  async generateConfig(domain: string, hostPort: number): Promise<void> {
    await this.generateHttpConfig(domain, hostPort);
  }

  /**
   * Menghapus file .conf jika project dihapus
   */
  async removeConfig(domain: string): Promise<void> {
    const confPath = path.join(this.confDir, `${domain}.conf`);
    if (fs.existsSync(confPath)) {
      fs.unlinkSync(confPath);
      this.logger.log(`Nginx config removed for ${domain}`);
      await this.reloadNginx();
    }
  }

  /**
   * Me-reload container portdock-nginx secara graceful
   */
  async reloadNginx(): Promise<void> {
    try {
      const containerId = await this.dockerService.getSystemNginxContainerId();
      if (!containerId) {
        this.logger.warn('portdock-nginx container not found, skip reload.');
        return;
      }
      const container = await this.dockerService.getContainer(containerId);
      const exec = await container.exec({
        Cmd: ['nginx', '-s', 'reload'],
        AttachStdout: true,
        AttachStderr: true,
      });
      await exec.start({});
      this.logger.log('Nginx reloaded successfully');
    } catch (err) {
      this.logger.error('Failed to reload Nginx', err);
    }
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  Request,
  ParseIntPipe,
  DefaultValuePipe,
  Ip,
} from '@nestjs/common';
import {
  ApiTags,
  ApiCookieAuth,
  ApiOperation,
  ApiQuery,
} from '@nestjs/swagger';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { ProjectsService } from './projects.service';
import { CreateProjectDto } from './dto/create-project.dto';
import { UpdateProjectDto } from './dto/update-project.dto';

@ApiTags('projects')
@ApiCookieAuth()
@UseGuards(JwtAuthGuard)
@Controller('projects')
export class ProjectsController {
  constructor(private projectsService: ProjectsService) {}

  @Post()
  @ApiOperation({ summary: 'Create a new project' })
  create(@Request() req: any, @Body() dto: CreateProjectDto, @Ip() ip: string) {
    return this.projectsService.create(req.user.id, dto, ip);
  }

  @Get()
  @ApiOperation({ summary: 'Get all projects' })
  @ApiQuery({ name: 'search', required: false })
  @ApiQuery({ name: 'status', required: false })
  @ApiQuery({ name: 'page', required: false })
  @ApiQuery({ name: 'limit', required: false })
  findAll(
    @Request() req: any,
    @Query('search') search?: string,
    @Query('status') status?: string,
    @Query('page', new DefaultValuePipe(1), ParseIntPipe) page?: number,
    @Query('limit', new DefaultValuePipe(10), ParseIntPipe) limit?: number,
